def us(t):return round(datetime.fromisoformat(t.replace('Z','+00:00')).timestamp()*1e6)
START=us(c['activity_start']);END=us(c['activity_end_exclusive']);CAP=us(c['quote_capture_horizon'])
class AuditTests(unittest.TestCase):
 def test_cash_cutoffs_and_continuity(self):
  self.assertEqual(START,us('2026-11-16T15:25:00+08:00'));self.assertEqual(END,us('2026-11-16T19:45:00+08:00'));self.assertLess(START,END)
  w=[x for x in d['ledger']if x['in_requested_window']];self.assertTrue(all(START<=us(x['exit_at'])<END for x in w));self.assertEqual(sum(Decimal(str(x['net_usd']))for x in w),Decimal(str(d['window_closed_s3_net_usd'])))
  self.assertFalse(any(x['in_requested_window']for x in d['ledger']if x['prior_partial_followup']))
  self.assertEqual(round(d['continuity']['prior_post_pr214_cash_usd']+d['window_closed_s3_net_usd'],2),d['cash_evidence']['post_pr214']['total_usd'])
  self.assertTrue(d['repeat_interval_metrics_recheck']['original_and_refetched_metrics_equal']);self.assertTrue(d['repeat_interval_metrics_recheck']['successful_history_extends_past_cutoff'])
  for scope in d['cash_evidence'].values():self.assertEqual(len(scope['closing_receipts']),len({(x['account_id'],x['deal_id'])for x in scope['closing_receipts']}))
 def test_quote_hashes_ranges_and_copy_coverage(self):
  intervals={}
  for r in d['quote_receipts']:
   b=gzip.decompress((P/'quotes'/r['filename']).read_bytes());self.assertEqual(hashlib.sha256(b).hexdigest(),r['sha256']);self.assertEqual(b.count(b'\n'),r['rows'])
   lo,hi=us(r['window_start']),us(r['through_exclusive']);self.assertLess(lo,hi);self.assertTrue(all(lo<=int(x[0])<hi for x in csv.reader(b.decode().splitlines())));self.assertEqual(r['new_broker_requests'],0)
   intervals.setdefault((r['account_id'],r['symbol']),[]).append((lo,hi))
  for rr in intervals.values():rr.sort();self.assertTrue(all(x[1]<=y[0]for x,y in zip(rr,rr[1:])))
  for t in d['ledger']:
   lo=us(t['exit_at']if t['prior_partial_followup']else t['entry_at'])-6_000_000;hi=min(us(t['exit_at'])+14_400_000_000,CAP)if t['exit_at']else END
